Your expense tracker is below. Add an expense with a name, category, amount and date, and it shows your month total, a budget bar and a spend breakdown by category. It works only while this page is open, so nothing is saved after you close it.

```page
<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<style>
  body{font-family:system-ui,sans-serif;margin:0;padding:16px;background:#f6f7f4;color:#1f2a24}
  h2{margin:0 0 12px}
  .card{background:#fff;border-radius:12px;padding:14px;margin-bottom:12px;box-shadow:0 1px 3px rgba(0,0,0,.08)}
  .row{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:8px}
  input,select,button{font:inherit;padding:8px;border:1px solid #c9d1cb;border-radius:8px}
  input,select{flex:1;min-width:110px}
  button{background:#2f7d55;color:#fff;border:none;cursor:pointer}
  button.del{background:none;color:#b3261e;padding:2px 8px}
  .big{font-size:28px;font-weight:700}
  .bar{height:10px;background:#e3e8e4;border-radius:6px;overflow:hidden;margin-top:6px}
  .fill{height:100%;background:#2f7d55}
  .over{background:#b3261e}
  .cat{margin:8px 0}
  .cat div.top{display:flex;justify-content:space-between}
  .item{display:flex;justify-content:space-between;align-items:center;padding:6px 0;border-bottom:1px solid #eef1ee}
  .small{color:#5f6b64;font-size:13px}
</style>
</head>
<body>
<h2>Monthly expenses</h2>

<div class="card">
  <div class="row">
    <select id="month"></select>
    <input id="budget" type="number" placeholder="Monthly budget (₹)" value="50000">
  </div>
  <div class="small">Spent this month</div>
  <div class="big" id="total">₹0</div>
  <div class="bar"><div class="fill" id="fill" style="width:0"></div></div>
  <div class="small" id="left"></div>
</div>

<div class="card">
  <div class="row">
    <input id="name" placeholder="What was it?">
    <input id="amt" type="number" placeholder="Amount (₹)">
  </div>
  <div class="row">
    <select id="cat">
      <option>Rent</option><option>Food</option><option>Travel</option>
      <option>Bills</option><option>Shopping</option><option>Health</option><option>Fun</option><option>Other</option>
    </select>
    <input id="date" type="date">
    <button type="button" id="add">Add</button>
  </div>
</div>

<div class="card"><b>By category</b><div id="cats"></div></div>
<div class="card"><b>Expenses</b><div id="list"></div></div>

<script>
var items=[];
var $=function(i){return document.getElementById(i)};
var fmt=function(n){return "₹"+Math.round(n).toLocaleString("en-IN")};
var now=new Date();
var today=now.toISOString().slice(0,10);
$("date").value=today;

function monthKey(d){return d.slice(0,7)}
function buildMonths(){
  var sel=$("month"),cur=sel.value,keys={};
  keys[monthKey(today)]=1;
  items.forEach(function(x){keys[monthKey(x.date)]=1});
  var list=Object.keys(keys).sort().reverse();
  sel.innerHTML="";
  list.forEach(function(k){
    var o=document.createElement("option");
    o.value=k;
    o.textContent=new Date(k+"-01T00:00:00").toLocaleString("en-IN",{month:"long",year:"numeric"});
    sel.appendChild(o);
  });
  sel.value=cur&&keys[cur]?cur:monthKey(today);
}

function render(){
  var m=$("month").value;
  var rows=items.filter(function(x){return monthKey(x.date)===m});
  var total=rows.reduce(function(s,x){return s+x.amt},0);
  var budget=parseFloat($("budget").value)||0;
  $("total").textContent=fmt(total);
  var pct=budget>0?Math.min(100,total/budget*100):0;
  var f=$("fill");
  f.style.width=pct+"%";
  f.className="fill"+(budget>0&&total>budget?" over":"");
  $("left").textContent=budget>0?(total>budget?"Over budget by "+fmt(total-budget):fmt(budget-total)+" left of "+fmt(budget)):"Set a budget to see what is left";

  var by={};
  rows.forEach(function(x){by[x.cat]=(by[x.cat]||0)+x.amt});
  var html="";
  Object.keys(by).sort(function(a,b){return by[b]-by[a]}).forEach(function(c){
    var p=total?by[c]/total*100:0;
    html+='<div class="cat"><div class="top"><span>'+c+'</span><span>'+fmt(by[c])+'</span></div><div class="bar"><div class="fill" style="width:'+p+'%"></div></div></div>';
  });
  $("cats").innerHTML=html||'<div class="small">Nothing yet.</div>';

  var lh="";
  rows.slice().sort(function(a,b){return a.date<b.date?1:-1}).forEach(function(x){
    lh+='<div class="item"><div>'+esc(x.name)+'<div class="small">'+x.cat+' · '+x.date+'</div></div><div>'+fmt(x.amt)+' <button type="button" class="del" data-id="'+x.id+'">✕</button></div></div>';
  });
  $("list").innerHTML=lh||'<div class="small">No expenses this month.</div>';
}

function esc(s){return s.replace(/[&<>"]/g,function(c){return{"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]})}

$("add").onclick=function(){
  var a=parseFloat($("amt").value);
  if(!(a>0))return;
  items.push({id:Date.now()+Math.random(),name:$("name").value.trim()||$("cat").value,cat:$("cat").value,amt:a,date:$("date").value||today});
  $("name").value="";$("amt").value="";
  var keep=monthKey($("date").value||today);
  buildMonths();$("month").value=keep;render();
};
$("list").onclick=function(e){
  var id=e.target.getAttribute("data-id");
  if(!id)return;
  items=items.filter(function(x){return String(x.id)!==id});
  buildMonths();render();
};
$("month").onchange=render;
$("budget").oninput=render;
buildMonths();render();
</script>
</body>
</html>
```
